import projects from "./data/projects";

const Projects = () => {
    return (
        <section className="projects">
            <div>
                <p className="text-small">This is my</p>
                <h2 className="text-h2">PROJECTS</h2>
                <p className="text-small">Computer Science</p>
            </div>

            <div>
                <div className="projects_card">
                    <img src="./assets/img/projects/GoIT.webp" />
                    <div className="projects_title">
                        <h3 className="text-h3">GoIT</h3>
                        <p className="text-small">with</p>
                        <h3 className="projects_type text-h3">Teamwork</h3>
                    </div>
                </div>
            </div>
        </section>
    );
}

export default Projects;
